import { loadWasm, wasmReady, isWasmReady, ready } from './loader.mjs';
import { InMemoryTransport } from './transport.mjs';
import { InMemoryStorage } from './storage.mjs';
import { NotLeaderError, RejectedError } from './errors.mjs';

export { RejectedError, NotLeaderError, TimeoutError } from './errors.mjs';

/**
 * Map raft_state number to human string for quick debugging.
 * Fallback to 'unknown' if not recognized.
 */
function roleFromState(raft_state) {
  switch (raft_state) {
    case 2: return 'leader';     // common raft-rs variant mapping
    case 1: return 'candidate';
    case 0: return 'follower';
    default: return 'unknown';
  }
}

/**
 * Plain ES6 Raft SDK around the raft-wasm exports.
 * - Pluggable transport: object with async send(fromId, msgs)
 * - Pluggable storage: object with async initialState(id) and persistReady(id, ready)
 * - App hook: apply(entry) called for each committed entry
 *
 * Message and Ready JSON shapes follow the WASM boundary schema, with u64s as strings
 * and bytes as base64 strings. Messages emitted by take_ready() can be routed directly
 * to other nodes' step() without re-encoding.
 *
 * Enhancements:
 * - Internal state cache: { role, term, lead, commitIndex, lastApplied, lastLogIndex }
 * - Optional callbacks: onStateUpdate(snap), onDrain()
 */
export class RaftNode {
  /**
   * @param {Object} opts
   * @param {string} opts.id - node ID (stringified u64)
   * @param {string[]} [opts.peers] - initial voters set (stringified u64 ids)
   * @param {number} opts.electionTick
   * @param {number} opts.heartbeatTick
   * @param {{ send(fromId: string, msgs: any[]): Promise<void>, register?: (node: RaftNode) => void }} opts.transport
   * @param {{ initialState?(id: string): Promise<object>, persistReady?(id: string, ready: any): Promise<void> }} [opts.storage]
   * @param {(entry: any) => Promise<void>|void} opts.apply - application state machine apply
   * @param {number} [opts.tickIntervalMs] - ms per raft tick, default ~100ms
   * @param {boolean} [opts.preVote] - default false
   * @param {boolean} [opts.checkQuorum] - default false
   * @param {(snap: any) => void} [opts.onStateUpdate] - observe state deltas
   * @param {() => void} [opts.onDrain] - called when Ready queue fully drained
   */
  constructor(opts) {
    this.id = String(opts.id);
    this.peers = Array.isArray(opts.peers) ? opts.peers.map(String) : [this.id];
    this.electionTick = opts.electionTick;
    this.heartbeatTick = opts.heartbeatTick;
    this.transport = opts.transport;
    this.storage = opts.storage || new InMemoryStorage();
    this.apply = opts.apply;
    this.tickIntervalMs = opts.tickIntervalMs ?? 100;
    this.preVote = !!opts.preVote;
    this.checkQuorum = !!opts.checkQuorum;
    this.debug = !!opts.debug;
    this.metrics = opts.metrics || null;
    this.onStateUpdate = typeof opts.onStateUpdate === 'function' ? opts.onStateUpdate : null;
    this.onDrain = typeof opts.onDrain === 'function' ? opts.onDrain : null;

    if (typeof this.apply !== 'function') {
      throw new Error('apply(entry) handler is required');
    }

    this._handle = null;
    this._tickTimer = null;
    this._running = false;
    this._tickBound = this._tick.bind(this);

    // Internal state cache for observability and synchronization
    this._role = 'unknown';
    this._term = 0;
    this._lead = null;
    this._commitIndex = 0;
    this._lastApplied = 0;
    this._lastLogIndex = 0;
    this._isApplying = false;

    // Events and waiters (leadership signals and commit/apply wait)
    this._stateChangeCbs = new Set();
    this._becameLeaderCbs = new Set();
    this._becameFollowerCbs = new Set();
    this._commitWaiters = new Set();
    this._applyWaiters = new Set();
    this._drainWaiters = new Set();

    // Additional event channels
    this._roleChangeCbs = new Set();
    this._commitAdvancedCbs = new Set();
    this._quorumActiveCbs = new Set();
    this._tickCbs = new Set();

    // Heartbeat round/quorum tracking (leader-side)
    this._hbRound = 0;
    this._hbRoundTerm = 0;
    this._hbAckSet = new Set();
    this._hbRoundEmitted = false;
    this._lastQuorumActiveTerm = 0;

    // Residency tick counter (reset on leader change)
    this._termResidencyTicks = 0;
  }

  _snapshot() {
    return {
      id: this.id,
      role: this._role,
      term: this._term,
      lead: this._lead,
      commitIndex: this._commitIndex,
      lastApplied: this._lastApplied,
      lastLogIndex: this._lastLogIndex,
    };
  }

  _emitStateIfChanged(prev) {
    const cur = this._snapshot();
    const changed =
      prev.role !== cur.role ||
      prev.term !== cur.term ||
      prev.lead !== cur.lead ||
      prev.commitIndex !== cur.commitIndex ||
      prev.lastApplied !== cur.lastApplied ||
      prev.lastLogIndex !== cur.lastLogIndex;

    if (changed) {
      if (this.onStateUpdate) {
        try { this.onStateUpdate(cur); } catch {}
      }
      if (prev.role !== cur.role) {
        try { this.metrics && typeof this.metrics.onRoleChange === 'function' && this.metrics.onRoleChange(prev.role, cur.role); } catch {}
        if (cur.role === 'leader') {
          this._emitTo(this._becameLeaderCbs, { term: this._term });
          // Reset residency and heartbeat round tracking on new leadership
          this._termResidencyTicks = 0;
          this._hbRound = 0;
          this._hbRoundTerm = this._term;
          this._hbAckSet = new Set();
          this._hbRoundEmitted = false;
        } else if (cur.role === 'follower') {
          this._emitTo(this._becameFollowerCbs, { term: this._term, lead: this._lead || null });
        }
        // Emit a dedicated roleChange event
        this._emitTo(this._roleChangeCbs, { role: cur.role, term: this._term, lead: this._lead || null });
      }
      this._emitTo(this._stateChangeCbs, cur);
      this._resolveIndexWaiters();
    }
  }

  _updateRoleLeadFromStatus(rawStatus) {
    if (!rawStatus) return;
    const prev = this._snapshot();
    const state = rawStatus.raft_state != null ? rawStatus.raft_state : rawStatus.raftState;
    if (state != null) {
      this._role = roleFromState(state);
    }
    if (rawStatus.lead != null) {
      this._lead = rawStatus.lead === '0' || rawStatus.lead === 0 ? null : String(rawStatus.lead);
    }
    if (rawStatus.term != null) {
      const t = Number(rawStatus.term);
      if (!Number.isNaN(t)) this._term = t;
    }
    this._emitStateIfChanged(prev);
  }

  _maybeUpdateFromHardState(hs) {
    if (!hs) return;
    const prev = this._snapshot();
    // Common shapes: { term, commit, vote } OR snake_case
    const term = hs.term != null ? hs.term : hs.currentTerm;
    if (term != null) {
      const t = Number(term);
      if (!Number.isNaN(t) && t > this._term) this._term = t;
    }
    const commit = hs.commit != null ? hs.commit : hs.commit_index;
    if (commit != null) {
      const c = Number(commit);
      if (!Number.isNaN(c) && c > this._commitIndex) this._commitIndex = c;
    }
    this._emitStateIfChanged(prev);
  }

  _maybeUpdateCommitIndex(val) {
    if (val == null) return;
    const v = Number(val);
    if (Number.isNaN(v)) return;
    if (v > this._commitIndex) {
      const prev = this._snapshot();
      const prevCommit = this._commitIndex;
      this._commitIndex = v;
      this._emitStateIfChanged(prev);
      if (this._commitIndex > prevCommit) {
        this._emitTo(this._commitAdvancedCbs, { commitIndex: this._commitIndex, term: this._term });
      }
    }
  }

  _maybeUpdateLastLogIndex(val) {
    if (val == null) return;
    const v = Number(val);
    if (Number.isNaN(v)) return;
    if (v > this._lastLogIndex) {
      const prev = this._snapshot();
      this._lastLogIndex = v;
      this._emitStateIfChanged(prev);
    }
  }

  _maybeUpdateLastApplied(val) {
    if (val == null) return;
    const v = Number(val);
    if (Number.isNaN(v)) return;
    if (v > this._lastApplied) {
      const prev = this._snapshot();
      this._lastApplied = v;
      this._emitStateIfChanged(prev);
    }
  }

  /**
   * Initialize wasm (if needed), create the Raft node in wasm, and start ticking.
   */
  async start() {
    if (!isWasmReady()) {
      await loadWasm();
    }
    const wasm = wasmReady();

    // Optional: load durable initial state from storage
    let bootstrap = null;
    if (this.storage.initialState) {
      try { bootstrap = await this.storage.initialState(this.id); } catch {}
    }

    const handle = await wasm.create_node({
      id: this.id,
      peers: this.peers,
      electionTick: Number(this.electionTick),
      heartbeatTick: Number(this.heartbeatTick),
      preVote: this.preVote,
      checkQuorum: this.checkQuorum,
      bootstrap: bootstrap,
    });

    this._handle = handle;

    this._running = true;

    // Allow transport to register this node instance (used by InMemoryTransport)
    if (typeof this.transport.register === 'function') {
      this.transport.register(this);
    }

    // Kick the periodic tick loop (only if interval > 0; allow manual ticking for tests)
    if (this.tickIntervalMs && this.tickIntervalMs > 0) {
      this._tickTimer = setInterval(this._tickBound, this.tickIntervalMs);
    }
  }

  /**
   * Stop ticking and free the underlying wasm node.
   */
  /**
   * Stop ticking and free the underlying wasm node.
   * Options:
   *  - drainApply: drain remaining Ready/apply before stopping
   *  - drainTicks: perform a few ticks to flush messages before draining
   */
  async stop(opts = {}) {
    const drainApply = !!opts.drainApply;
    const drainTicks = !!opts.drainTicks;

    if (this._handle != null && (drainApply || drainTicks)) {
      const wasm = wasmReady();
      if (drainTicks) {
        for (let i = 0; i < 5; i++) {
          await this._tick();
        }
      }
      // Drain while there is Ready pending
      while (await wasm.has_ready(this._handle)) {
        await this._drainReady();
      }
    }

    this._running = false;
    this._stopped = true;

    if (this._tickTimer) {
      clearInterval(this._tickTimer);
      this._tickTimer = null;
    }
    if (this._tickTimeout) {
      clearTimeout(this._tickTimeout);
      this._tickTimeout = null;
    }

    this._tickBound = () => {};

    await new Promise(r => setImmediate(r));

    if (this._handle != null) {
      try {
        const wasm = wasmReady();
        await wasm.free(this._handle);
      } finally {
        this._handle = null;
      }
    }

    if (this.debug) console.log('[raft-node]', this.id, 'stop() completed, timers cleared');
  }

  /**
   * Query enriched status from the wasm layer merged with cached indices.
   * Returns: { role, term, lead, commitIndex, lastApplied, lastLogIndex, raft_state }
   */
  async status() {
    if (!this._running || this._handle == null) return null;
    const wasm = wasmReady();
    const raw = await wasm.status(this._handle);
    this._updateRoleLeadFromStatus(raw);
    return {
      role: this._role,
      term: this._term,
      lead: this._lead,
      commitIndex: this._commitIndex,
      lastApplied: this._lastApplied,
      lastLogIndex: this._lastLogIndex,
      raft_state: raw && (raw.raft_state != null ? raw.raft_state : (raw.raftState != null ? raw.raftState : undefined)),
    };
  }

  /**
   * Propose a new entry. Accepts Uint8Array, ArrayBuffer, or string.
   * Strings are utf-8 encoded.
   */
  async propose(data) {
    if (!this._running || this._handle == null) return;
    const wasm = wasmReady();

    if (this._isApplying) {
      try { this.metrics?.onRejected && this.metrics.onRejected('Reentrancy'); } catch {}
      throw new RejectedError('Propose from apply() context is not allowed; use schedulePropose()', 'Reentrancy');
    }
    // Allow propose if leader hint points to self (status may lag briefly) or single-node cluster
    const selfIsLeaderHint = this._lead && this._lead === this.id;
    const singleNode = Array.isArray(this.peers) && this.peers.length === 1 && this.peers[0] === this.id;
    if (this._role !== 'leader' && !selfIsLeaderHint && !singleNode) {
      const hint = this._lead ? { id: String(this._lead) } : undefined;
      try { this.metrics?.onRejected && this.metrics.onRejected('NotLeader', { term: this._term, leaderId: this._lead || null }); } catch {}
      throw new NotLeaderError(this._term, this._lead || null, hint);
    }

    let bytes;
    if (data instanceof Uint8Array) {
      bytes = data;
    } else if (typeof data === 'string') {
      bytes = new TextEncoder().encode(data);
    } else if (data instanceof ArrayBuffer) {
      bytes = new Uint8Array(data);
    } else {
      throw new Error('propose(data) expects Uint8Array | ArrayBuffer | string');
    }

    await wasm.propose(this._handle, bytes);
    try { this.metrics?.onPropose && this.metrics.onPropose(); } catch {}
    // Drain immediately to persist and commit faster (especially single-node)
    await this._drainReady();
  }

  /**
   * Client-facing request helper with auto-forwarding and optional waits.
   * opts: { autoForward?: boolean=true, waitFor?: 'none'|'commit'|'apply'='none', timeout?: number, abortSignal?: AbortSignal }
   * Returns: { index, term }
   */
  async clientRequest(data, opts = {}) {
    if (!this._running || this._handle == null) throw new Error('Not running');
    const autoForward = opts.autoForward !== false;
    const waitFor = opts.waitFor || 'none';
    const timeoutMs = opts.timeout;
    const abortSignal = opts.abortSignal;

    const selfIsLeaderHint = this._lead && this._lead === this.id;
    const singleNode = Array.isArray(this.peers) && this.peers.length === 1 && this.peers[0] === this.id;

    if (this._role !== 'leader' && !selfIsLeaderHint && !singleNode) {
      const err = new NotLeaderError(this._term, this._lead || null, this._lead ? { id: String(this._lead) } : undefined);
      if (autoForward && this._lead && this._lead !== this.id && this.transport && typeof this.transport.sendClientRequest === 'function') {
        const fwd = this.transport.sendClientRequest(this._lead, data, { autoForward: false, waitFor, timeout: timeoutMs, abortSignal });
        return await this._withTimeout(fwd, timeoutMs, abortSignal);
      }
      throw err;
    }

    const before = Number(this._lastLogIndex) || 0;
    const drainP = this._awaitDrainOnce();
    await this.propose(data);
    await this._withTimeout(drainP, timeoutMs, abortSignal);

    const index = Number(this._lastLogIndex) > before ? Number(this._lastLogIndex) : (before + 1);
    const term = Number(this._term);

    if (waitFor === 'commit') {
      await this.waitForCommit(index, { localApply: false, timeout: timeoutMs, abortSignal });
    } else if (waitFor === 'apply') {
      await this.waitForCommit(index, { localApply: true, timeout: timeoutMs, abortSignal });
    }

    return { index, term };
  }

  // Safe deferral when called from within apply() context
  async schedulePropose(data, opts = {}) {
    return new Promise((resolve, reject) => {
      setImmediate(() => {
        this.clientRequest(data, opts).then(resolve, reject);
      });
    });
  }

  // Event subscriptions and waiting primitives
  onStateChange(cb) {
    if (typeof cb !== 'function') return () => {};
    this._stateChangeCbs.add(cb);
    return () => this._stateChangeCbs.delete(cb);
  }
  onBecameLeader(cb) {
    if (typeof cb !== 'function') return () => {};
    this._becameLeaderCbs.add(cb);
    return () => this._becameLeaderCbs.delete(cb);
  }
  onBecameFollower(cb) {
    if (typeof cb !== 'function') return () => {};
    this._becameFollowerCbs.add(cb);
    return () => this._becameFollowerCbs.delete(cb);
  }

  // New: granular event subscriptions
  onRoleChange(cb) {
    if (typeof cb !== 'function') return () => {};
    this._roleChangeCbs.add(cb);
    return () => this._roleChangeCbs.delete(cb);
  }

  onCommitAdvanced(cb) {
    if (typeof cb !== 'function') return () => {};
    this._commitAdvancedCbs.add(cb);
    return () => this._commitAdvancedCbs.delete(cb);
  }

  onQuorumActive(cb) {
    if (typeof cb !== 'function') return () => {};
    this._quorumActiveCbs.add(cb);
    return () => this._quorumActiveCbs.delete(cb);
  }

  onTick(cb) {
    if (typeof cb !== 'function') return () => {};
    this._tickCbs.add(cb);
    return () => this._tickCbs.delete(cb);
  }

  async waitForLeader(timeoutMs) {
    if (!this._running) throw new Error('Not running');
    if (this._lead && this._role !== 'candidate') return this._lead;
    const p = new Promise((resolve) => {
      const off = this.onStateChange((s) => {
        if (s && s.lead && s.role !== 'candidate') {
          off();
          resolve(String(s.lead));
        }
      });
    });
    return this._withTimeout(p, timeoutMs);
  }

  async waitForCommit(index, opts = {}) {
    if (!this._running) throw new Error('Not running');
    const localApply = !!opts.localApply;
    const timeoutMs = opts.timeout;
    const abortSignal = opts.abortSignal;

    const needsApply = localApply === true;
    const waiters = [];

    if (Number(this._commitIndex) >= Number(index)) {
      if (!needsApply || Number(this._lastApplied) >= Number(index)) {
        return;
      }
    }

    const commitP = new Promise((resolve, reject) => {
      const waiter = { index: Number(index), resolve, reject };
      this._commitWaiters.add(waiter);
      this._resolveIndexWaiters();
    });
    waiters.push(commitP);

    if (needsApply) {
      const applyP = new Promise((resolve, reject) => {
        const waiter = { index: Number(index), resolve, reject };
        this._applyWaiters.add(waiter);
        this._resolveIndexWaiters();
      });
      waiters.push(applyP);
    }

    const all = Promise.all(waiters).then(() => undefined);
    return this._withTimeout(all, timeoutMs, abortSignal);
  }

  async barrier() {
    if (!this._running) return;
    if (this._role === 'leader') {
      const target = Number(this._lastLogIndex) || 0;
      if (target > 0) await this.waitForCommit(target, { localApply: false });
    } else {
      const target = Number(this._commitIndex) || 0;
      if (target > 0) await this.waitForCommit(target, { localApply: true });
    }
  }

  /**
   * Linearizable read (lease-based): leader-gated, requires stability window (checkQuorum recommended).
   * Returns a commit index that is safe for read-after-write visibility under leader lease.
   */
  async readIndex(opts = {}) {
    if (!this._running || this._handle == null) throw new Error('Not running');
    const timeoutMs = opts.timeout;
    const abortSignal = opts.abortSignal;

    const selfIsLeaderHint = this._lead && this._lead === this.id;
    const singleNode = Array.isArray(this.peers) && this.peers.length === 1 && this.peers[0] === this.id;

    if (this._role !== 'leader' && !selfIsLeaderHint && !singleNode) {
      const hint = this._lead ? { id: String(this._lead) } : undefined;
      try { this.metrics?.onRejected && this.metrics.onRejected('NotLeader', { term: this._term, leaderId: this._lead || null }); } catch {}
      throw new NotLeaderError(this._term, this._lead || null, hint);
    }

    // Ensure a stability window with heartbeats before serving the read.
    await this._withTimeout(this._stableWindow(timeoutMs), timeoutMs, abortSignal);
    return Number(this._commitIndex) || 0;
  }

  /**
   * Deterministic control helpers (parity with ThreadedRaftNode)
   */

  /**
   * Transfer leadership to a target peer by stepping a MsgTransferLeader locally.
   * Resolves when the target is the stable leader (or rejects on timeout).
   */
  async transferLeadership(targetId, timeoutMs) {
    if (!this._running || this._handle == null) throw new Error('Not running');
    const tid = String(targetId);
    // trigger transfer by stepping a local control message
    const msg = { from: String(tid), to: String(this.id), msgType: 13 };
    await this.step(msg);

    await this._withTimeout(this._waitForLeadId(tid), timeoutMs);
    await this._stableWindow(timeoutMs);
  }

  /**
   * Step down from leadership by triggering an immediate election (MsgTimeoutNow).
   * Resolves when this node is no longer leader; if already follower, resolves immediately.
   */
  async stepDown(timeoutMs) {
    if (!this._running || this._handle == null) throw new Error('Not running');
    if (this._role !== 'leader' || (this._lead && this._lead !== this.id)) return;

    // Choose a transferee (any peer that's not self) and request transfer
    const candidates = Array.isArray(this.peers) ? this.peers.map(String).filter((pid) => pid !== this.id) : [];
    if (!candidates.length) return;
    const target = candidates[0];
    // Step a MsgTransferLeader to self as if coming from the transferee
    const msg = { from: String(target), to: String(this.id), msgType: 13 };
    await this.step(msg);

    const p = new Promise((resolve) => {
      const off = this.onStateChange((s) => {
        if (s && s.lead && String(s.lead) !== String(this.id)) {
          off();
          resolve();
        }
      });
    });
    await this._withTimeout(p, timeoutMs);
    await this._stableWindow(timeoutMs);
  }

  /**
   * Resolve after n majority heartbeat rounds have completed in the current term.
   * Resets if the term changes.
   */
  async waitForHeartbeatRound(n = 1, options = {}) {
    const count = Number(n) || 1;
    const signal = options && options.signal;
    const termAtStart = this._term;

    // Fast path: if we already observed quorum in the current term and n <= 1
    if (count <= 1 && this._lastQuorumActiveTerm === termAtStart) {
      return;
    }

    let rounds = 0;
    return this._withTimeout(new Promise((resolve, reject) => {
      const off = this.onQuorumActive((evt) => {
        if (!evt || typeof evt.term !== 'number') return;
        if (evt.term !== this._term || evt.term !== termAtStart) return;
        rounds++;
        if (rounds >= count) {
          try { off(); } catch {}
          resolve();
        }
      });
      if (signal) {
        const onAbort = () => { try { off(); } catch {}; reject(Object.assign(new Error('Operation aborted'), { code: 'AbortError' })); };
        if (signal.aborted) return onAbort();
        signal.addEventListener('abort', onAbort, { once: true });
      }
    }), undefined, signal);
  }

  /**
   * Event-driven waiter: resolves when this node is leader and, if required, has obtained quorum in the current term.
   * options: { requireQuorum = true, minTermResidencyTicks = 0, signal?: AbortSignal }
   */
  async waitForLeaderStable(options = {}) {
    if (!this._running || this._handle == null) throw new Error('Not running');
    const requireQuorum = options.requireQuorum !== false;
    const minTicks = Number(options.minTermResidencyTicks || 0);
    const signal = options.signal;

    const satisfied = () => {
      const isLeader = this._role === 'leader' || (this._lead && this._lead === this.id);
      const quorumOk = !requireQuorum || (this._lastQuorumActiveTerm === this._term);
      const ticksOk = this._termResidencyTicks >= minTicks;
      return isLeader && quorumOk && ticksOk;
    };

    // Fast path
    if (satisfied()) return;

    return this._withTimeout(new Promise((resolve, reject) => {
      let offRole = () => {};
      let offQuorum = () => {};
      let offTick = () => {};

      const tryResolve = () => {
        if (satisfied()) {
          try { offRole(); offQuorum(); offTick(); } catch {}
          resolve();
        }
      };

      offRole = this.onRoleChange((rc) => {
        if (rc && rc.role === 'leader') {
          // Reset residency ticks and immediately trigger a heartbeat round
          this._termResidencyTicks = 0;
          this.sendHeartbeat().catch(() => {});
          tryResolve();
        } else {
          // role changed away from leader; reset residency ticks
          this._termResidencyTicks = 0;
        }
      });

      offQuorum = this.onQuorumActive((_evt) => {
        tryResolve();
      });

      if (minTicks > 0) {
        offTick = this.onTick(() => tryResolve());
      }

      if (signal) {
        const onAbort = () => { try { offRole(); offQuorum(); offTick(); } catch {}; reject(Object.assign(new Error('Operation aborted'), { code: 'AbortError' })); };
        if (signal.aborted) return onAbort();
        signal.addEventListener('abort', onAbort, { once: true });
      }
    }), undefined, signal);
  }

  /**
   * Wait until a stable leader exists using the new event-driven waiter.
   * Kept for backward compatibility; maps timeout into AbortSignal externally if desired.
   */
  async runUntilStableLeader(timeoutMs) {
    const leaderId = await this.waitForLeader(timeoutMs);
    await this._stableWindow(timeoutMs);
    return leaderId;
  }

  // Internals for deterministic control
  _waitForLeadId(targetId) {
    const tid = String(targetId);
    if (this._lead && String(this._lead) === tid) return Promise.resolve();
    return new Promise((resolve) => {
      const off = this.onStateChange((s) => {
        if (s && s.lead && String(s.lead) === tid) {
          off();
          resolve();
        }
      });
    });
  }

  _stableWindow(timeoutMs) {
    // consider two heartbeat periods as stability window
    const hb = Number(this.heartbeatTick || 1);
    const tickMs = Number(this.tickIntervalMs || 100);
    const windowMs = Math.max(1, hb) * tickMs * 2;

    return this._withTimeout(new Promise((resolve) => {
      let lastChange = Date.now();
      const off = this.onStateChange(() => { lastChange = Date.now(); });
      const check = () => {
        if (Date.now() - lastChange >= windowMs) {
          off();
          resolve();
        } else {
          setTimeout(check, Math.min(50, Math.max(10, windowMs / 10)));
        }
      };
      setTimeout(check, windowMs);
    }), timeoutMs);
  }

  _emitTo(set, payload) {
    for (const cb of Array.from(set)) {
      try { cb(payload); } catch {}
    }
  }

  _resolveIndexWaiters() {
    for (const w of Array.from(this._commitWaiters)) {
      if (Number(this._commitIndex) >= Number(w.index)) {
        this._commitWaiters.delete(w);
        try { w.resolve(); } catch {}
      }
    }
    for (const w of Array.from(this._applyWaiters)) {
      if (Number(this._lastApplied) >= Number(w.index)) {
        this._applyWaiters.delete(w);
        try { w.resolve(); } catch {}
      }
    }
  }

  _rejectAllWaiters(err) {
    for (const w of Array.from(this._commitWaiters)) {
      this._commitWaiters.delete(w);
      try { w.reject(err); } catch {}
    }
    for (const w of Array.from(this._applyWaiters)) {
      this._applyWaiters.delete(w);
      try { w.reject(err); } catch {}
    }
  }

  _withTimeout(p, timeoutMs, abortSignal) {
    if (!timeoutMs && !abortSignal) return p;
    return new Promise((resolve, reject) => {
      let settled = false;
      let to = null;
      const onAbort = () => {
        if (settled) return;
        settled = true;
        reject(Object.assign(new Error('Operation aborted'), { code: 'AbortError' }));
      };
      if (timeoutMs && timeoutMs > 0) {
        to = setTimeout(() => {
          if (settled) return;
          settled = true;
          reject(Object.assign(new Error('Operation timed out'), { code: 'Timeout' }));
        }, timeoutMs);
      }
      if (abortSignal) {
        if (abortSignal.aborted) {
          onAbort();
          return;
        }
        abortSignal.addEventListener('abort', onAbort, { once: true });
      }
      p.then((v) => {
        if (settled) return;
        settled = true;
        if (to) clearTimeout(to);
        if (abortSignal) abortSignal.removeEventListener('abort', onAbort);
        resolve(v);
      }, (err) => {
        if (settled) return;
        settled = true;
        if (to) clearTimeout(to);
        if (abortSignal) abortSignal.removeEventListener('abort', onAbort);
        reject(err);
      });
    });
  }

  _awaitDrainOnce() {
    return new Promise((resolve) => {
      this._drainWaiters.add(resolve);
    });
  }

  // Deterministic testing helpers (manual tick driving)
  async manualTick() {
    return this._tick();
  }

  async advanceTicks(n = 1) {
    const count = Number(n) || 0;
    for (let i = 0; i < count; i++) {
      await this._tick();
    }
  }

  /**
   * Step an incoming raft message (object from Ready.messages or decoded from your transport).
   * The object should match the JSON boundary schema (u64 as strings).
   */
  async step(msg) {
    if (!this._running || this._handle == null) return;
    const wasm = wasmReady();

    // Track heartbeat responses for quorum activity (leader side)
    try {
      const mt = msg && (msg.msg_type ?? msg.msgType);
      if (mt === 9 /* MsgHeartbeatResponse */ && this._role === 'leader') {
        const from = String(msg && (msg.from != null ? msg.from : '')) || '';
        // Only count responses within the current term's round
        if (this._hbRoundTerm === this._term) {
          this._hbAckSet.add(from);
          const voters = Array.isArray(this.peers) ? this.peers.length : 0;
          const quorum = Math.floor(voters / 2) + 1;
          const requiredAcks = Math.max(0, quorum - 1); // exclude leader self
          if (!this._hbRoundEmitted && this._hbAckSet.size >= requiredAcks) {
            this._hbRoundEmitted = true;
            this._lastQuorumActiveTerm = this._term;
            this._emitTo(this._quorumActiveCbs, {
              term: this._term,
              majorityAcks: this._hbAckSet.size,
              quorumSize: quorum,
              leaderId: this.id,
            });
          }
        }
      }
    } catch {}

    await wasm.step(this._handle, msg);
    // Optionally process readies immediately after an inbound message
    await this._drainReady();
  }

  // Explicitly trigger an election (RawNode::campaign)
  async campaign() {
    if (!this._running || this._handle == null) return;
    const wasm = wasmReady();
    await wasm.campaign(this._handle);
    await this._drainReady();
  }

  // Proactively trigger heartbeats (MsgBeat) to accelerate quorum acquisition after becoming leader
  async sendHeartbeat() {
    if (!this._running || this._handle == null) return;
    // Step a MsgBeat (1) to self; wasm layer will emit heartbeats to peers on next ready
    const msg = { from: String(this.id), to: String(this.id), msgType: 1 };
    await this.step(msg);
  }

  // Internal periodic tick
  async _tick() {
    if (this._stopped || !this._running || this._handle == null) return;
    const wasm = wasmReady();

    // Update role/lead snapshot cheaply each tick
    try {
      const raw = await wasm.status(this._handle);
      this._updateRoleLeadFromStatus(raw);
    } catch {}

    await wasm.tick(this._handle);
    await this._drainReady();
    if (this._role === 'leader') {
      this._termResidencyTicks++;
    }
    this._emitTo(this._tickCbs, { term: this._term });
  }

  // Drain Ready: persist -> send -> apply -> advance (repeat while has_ready)
  async _drainReady() {
    if (!this._running || this._handle == null) return;
    const wasm = wasmReady();

    // eslint-disable-next-line no-constant-condition
    while (true) {
      const has = await wasm.has_ready(this._handle);
      if (!has) break;

      const ready = await wasm.take_ready(this._handle);
      // Debug: observe Ready contents during orchestration (guarded by RAFT_DEBUG)
      if (this.debug && process.env.RAFT_DEBUG === '1') {
        console.log('[ready]', JSON.stringify({
          entries: (ready && ready.entries && ready.entries.length) || 0,
          committedEntries: (ready && ready.committedEntries && ready.committedEntries.length) || 0,
          messages: (ready && ready.messages && ready.messages.length) || 0,
          persistedMessages: (ready && ready.persistedMessages && ready.persistedMessages.length) || 0,
          mustSync: !!(ready && ready.mustSync),
          hardState: (ready && ready.hardState) || null
        }, null, 2));
      }

      // Update from hardState (term/commit) before persistence
      if (ready && ready.hardState) {
        this._maybeUpdateFromHardState(ready.hardState);
      }

      // Track lastLogIndex from new entries to persist
      if (ready && Array.isArray(ready.entries) && ready.entries.length) {
        let maxIdx = 0;
        for (const e of ready.entries) {
          const n = Number(e && (e.index ?? e.idx));
          if (!Number.isNaN(n) && n > maxIdx) maxIdx = n;
        }
        if (maxIdx > 0) this._maybeUpdateLastLogIndex(maxIdx);
      }


      // Persist durability at host level first (fsync in real adapters)
      if (this.storage.persistReady) {
        await this.storage.persistReady(this.id, ready);
      }
      // Inform WASM raft that persistence is complete (writes to MemStorage)
      await wasm.persist_ready(this._handle);

      // After persistence, send Ready messages (safe after durable persist)
      // Detect start of a heartbeat round when leader emits heartbeats
      const hasHeartbeat = (arr) => Array.isArray(arr) && arr.some((m) => (m && ((m.msg_type ?? m.msgType) === 8)));
      if (this._role === 'leader' && (hasHeartbeat(ready && ready.messages) || hasHeartbeat(ready && ready.persistedMessages))) {
        this._hbRound += 1;
        this._hbRoundTerm = this._term;
        this._hbAckSet = new Set();
        this._hbRoundEmitted = false;
      }
      if (ready.messages && ready.messages.length) {
        await this.transport.send(this.id, ready.messages);
      }
      if (ready.persistedMessages && ready.persistedMessages.length) {
        await this.transport.send(this.id, ready.persistedMessages);
      }

      // Apply committed entries from Ready (if any) before advancing append
      if (ready && ready.committedEntries && ready.committedEntries.length) {
        let maxAppliedReady = 0;
        try {
          this._isApplying = true;
          for (const e of ready.committedEntries) {
            const idx = Number(e && (e.index ?? e.idx));
            if (!Number.isNaN(idx) && idx > maxAppliedReady) maxAppliedReady = idx;
            // Track lastLogIndex based on committed entries as well
            if (!Number.isNaN(idx)) this._maybeUpdateLastLogIndex(idx);
            // Optional storage-coupled apply hook with access to the same DB handle
            if (this.storage && typeof this.storage.applyWithDb === 'function' && typeof this.storage.getDb === 'function') {
              try { await this.storage.applyWithDb(e, this.storage.getDb()); } catch {}
            }
            await this.apply(e);
          }
        } finally {
          this._isApplying = false;
        }
        if (maxAppliedReady > 0) {
          this._maybeUpdateLastApplied(maxAppliedReady);
        }
      }

      // Split-phase using LightReady: persist -> advance_append -> send/apply from LightReady -> advance_apply
      let lr = null;
      try {
        lr = await wasm.advance_append(this._handle);
      } catch (e) {
        // Some Ready cycles do not require an append advance; ignore harmless guard from wasm
        const msg = String(e && (e.message || e));
        if (!msg.includes('advance_append called without pending ready')) {
          throw e;
        }
      }
      // Debug LightReady summary (guarded by RAFT_DEBUG)
      try {
        if (this.debug && process.env.RAFT_DEBUG === '1') {
          console.log('[lightReady]', JSON.stringify({
            commitIndex: (lr && (lr.commitIndex ?? lr.commit_index)) || null,
            messages: (lr && lr.messages && lr.messages.length) || 0,
            committedEntries: (lr && lr.committedEntries && lr.committedEntries.length) || 0
          }, null, 2));
        }
      } catch {}

      // Commit index reported by LightReady
      if (lr && (lr.commitIndex != null || lr.commit_index != null)) {
        this._maybeUpdateCommitIndex(lr.commitIndex != null ? lr.commitIndex : lr.commit_index);
      }

      // Send outgoing messages after advancing append: LightReady.messages
      if (lr && lr.messages && lr.messages.length) {
        // Detect start of a heartbeat round when leader emits heartbeats
        const hasHeartbeat = (arr) => Array.isArray(arr) && arr.some((m) => (m && ((m.msg_type ?? m.msgType) === 8)));
        if (this._role === 'leader' && hasHeartbeat(lr.messages)) {
          this._hbRound += 1;
          this._hbRoundTerm = this._term;
          this._hbAckSet = new Set();
          this._hbRoundEmitted = false;
        }
        await this.transport.send(this.id, lr.messages);
      }

      // Apply any committed entries emitted in LightReady
      if (lr && lr.committedEntries && lr.committedEntries.length) {
        let maxApplied = 0;
        try {
          this._isApplying = true;
          for (const e of lr.committedEntries) {
            const idx = Number(e && (e.index ?? e.idx));
            if (!Number.isNaN(idx) && idx > maxApplied) maxApplied = idx;
            // Track lastLogIndex based on committed entries as well
            if (!Number.isNaN(idx)) this._maybeUpdateLastLogIndex(idx);
            // Optional storage-coupled apply hook with access to the same DB handle
            if (this.storage && typeof this.storage.applyWithDb === 'function' && typeof this.storage.getDb === 'function') {
              try { await this.storage.applyWithDb(e, this.storage.getDb()); } catch {}
            }
            await this.apply(e);
          }
        } finally {
          this._isApplying = false;
        }
        if (maxApplied > 0) {
          this._maybeUpdateLastApplied(maxApplied);
        }
      }

      // Finalize apply phase
      if (typeof wasm.advance_apply === 'function') {
        await wasm.advance_apply(this._handle);
      } else {
        await wasm.advance(this._handle);
      }
    }

    // Resolve waiter queues
    this._resolveIndexWaiters();

    // Resolve any one-shot drain waiters
    if (this._drainWaiters && this._drainWaiters.size) {
      for (const resolve of Array.from(this._drainWaiters)) {
        this._drainWaiters.delete(resolve);
        try { resolve(); } catch {}
      }
    }

    // Notify drain completion to outer host (used by tests/barriers)
    if (this.onDrain) {
      try { this.onDrain(); } catch {}
    }
  }
}

/**
 * Optional helper: resolve with the first node that becomes a stable leader.
 * nodes: array of RaftNode/ThreadedRaftNode
 * options: { requireQuorum = true, minTermResidencyTicks = 0, signal?: AbortSignal }
 */
export async function waitForFirstStableLeader(nodes, options = {}) {
  const requireQuorum = options.requireQuorum !== false;
  const minTicks = Number(options.minTermResidencyTicks || 0);
  const outerSignal = options.signal;
  const ac = new AbortController();
  if (outerSignal) {
    if (outerSignal.aborted) ac.abort();
    else outerSignal.addEventListener('abort', () => ac.abort(), { once: true });
  }
  const makeWait = (n) =>
    n.waitForLeaderStable({ requireQuorum, minTermResidencyTicks: minTicks, signal: ac.signal }).then(() => n);
  try {
    const winner = await Promise.any(nodes.map(makeWait));
    ac.abort();
    return winner;
  } catch (e) {
    ac.abort();
    throw e;
  }
}

/**
 * Helper: wait until a leader is ready for client operations.
 *
 * Semantics (best-effort, host-driven):
 *  - Ensures a leader exists and (optionally) has obtained quorum / residency.
 *  - Waits for all known log entries to be committed (and optionally applied) locally.
 *  - Optionally issues a lease-based read barrier via readIndex().
 *
 * options: {
 *   leaderTimeoutMs?: number,
 *   commitTimeoutMs?: number,
 *   leaseTimeoutMs?: number,
 *   requireQuorum?: boolean,
 *   minTermResidencyTicks?: number,
 *   waitForApply?: boolean,
 *   ensureLease?: boolean,
 *   signal?: AbortSignal,
 * }
 */
export async function waitForReadyLeader(node, options = {}) {
  const {
    leaderTimeoutMs = 5000,
    commitTimeoutMs = 8000,
    leaseTimeoutMs = 2000,
    requireQuorum,
    minTermResidencyTicks = 0,
    waitForApply = true,
    ensureLease = true,
    signal,
  } = options || {};

  if (!node || typeof node !== 'object') {
    throw new Error('waitForReadyLeader(node, options): node is required');
  }

  const id = String(node.id ?? '');
  const peers = Array.isArray(node.peers) ? node.peers.map(String) : null;
  const isSingleNode = !!(id && peers && peers.length === 1 && peers[0] === id);
  const requireQuorumResolved = typeof requireQuorum === 'boolean'
    ? requireQuorum
    : !isSingleNode;

  // 1) Wait for a stable leader if supported, otherwise just any leader
  if (typeof node.waitForLeaderStable === 'function') {
    await node.waitForLeaderStable({
      requireQuorum: requireQuorumResolved,
      minTermResidencyTicks,
      signal,
    });
  } else if (typeof node.waitForLeader === 'function') {
    await node.waitForLeader(leaderTimeoutMs);
  } else {
    throw new Error('waitForReadyLeader: node does not expose waitForLeader or waitForLeaderStable');
  }

  // 2) Ensure backlog up to current lastLogIndex/commitIndex is committed (and optionally applied) locally
  if (typeof node.status === 'function' && typeof node.waitForCommit === 'function') {
    const st = await node.status();
    const lastLogIndex = st && (st.lastLogIndex != null ? Number(st.lastLogIndex) : undefined);
    const commitIndex = st && (st.commitIndex != null ? Number(st.commitIndex) : undefined);
    const targetIndex = Number.isFinite(lastLogIndex) && lastLogIndex > 0
      ? lastLogIndex
      : (Number.isFinite(commitIndex) ? commitIndex : 0);

    if (targetIndex > 0) {
      const waitOpts = {};
      if (waitForApply) waitOpts.localApply = true;
      if (commitTimeoutMs != null) waitOpts.timeout = commitTimeoutMs;
      if (signal) waitOpts.abortSignal = signal;
      await node.waitForCommit(targetIndex, waitOpts);
    }
  }

  // 3) Optional lease/read barrier for leaders that support readIndex()
  if (ensureLease && typeof node.readIndex === 'function') {
    const readOpts = {};
    if (leaseTimeoutMs != null) readOpts.timeout = leaseTimeoutMs;
    if (signal) readOpts.abortSignal = signal;
    await node.readIndex(readOpts);
  }
}

export function leaderForwarder(transport, getLeaderId) {
  if (!transport || typeof transport.sendClientRequest !== 'function') {
    throw new Error('leaderForwarder requires a transport with sendClientRequest(leaderId, data, opts)');
  }
  if (typeof getLeaderId !== 'function') {
    throw new Error('leaderForwarder requires getLeaderId(): Promise<string>');
  }
  return async (data, opts = {}) => {
    const lid = await getLeaderId();
    return transport.sendClientRequest(lid, data, opts);
  };
}

